import json
n=30
g=[[0]*n for _ in range(n)]
# preserve the given outer frame: rows/cols 1 and 25 from coordinate 1 through 25
for c in range(1,26):
    g[1][c]=5; g[25][c]=5
for r in range(1,26):
    g[r][1]=5; g[r][25]=5
# inner area first becomes color 2
for r in range(2,25):
    for c in range(2,25): g[r][c]=2
# nested inset frame, color 5; its enclosed center remains background 0
for c in range(3,24):
    g[3][c]=5; g[23][c]=5
for r in range(3,24):
    g[r][3]=5; g[r][23]=5
# restore inner center to background
for r in range(4,23):
    for c in range(4,23): g[r][c]=0
print(json.dumps({'action':'submit','grid':g},separators=(',',':')))

